package com.finanscore.scoring.infrastructure;import jakarta.persistence.*;import java.math.*;@Entity @Table(name="simulated_credit_profile") public class SimulatedCreditProfileEntity{@Id @Column(name="user_id")public Long userId;@Column(name="document_number")public String documentNumber;@Column(name="display_name")public String displayName;@Column(name="monthly_income")public BigDecimal monthlyIncome;@Column(name="monthly_expenses")public BigDecimal monthlyExpenses;@Column(name="monthly_obligations")public BigDecimal monthlyObligations;@Column(name="employment_months")public int employmentMonths;@Column(name="active_obligations")public int activeObligations;@Column(name="payment_history_score")public int paymentHistoryScore;@Column(name="delinquency_alerts")public int delinquencyAlerts;}